const need = env.get('NEED') || 'control';
const h = msg.req.headers.authorization || '';
const token = h.startsWith('Bearer ') ? h.slice(7) : null;
function deny(code, pesan){ msg.statusCode = code; msg.payload = {ok:false, pesan}; return [null, msg]; }
if (!token) return deny(401, 'Silakan login.');
let p;
try { p = jwt.verify(token, env.get('JWT_SECRET')); } catch (e) { return deny(401, 'Sesi tidak valid atau kedaluwarsa.'); }
if (need === 'super') { if (p.role !== 'super_admin') return deny(403, 'Hanya super admin.'); }
else if (p.role !== 'super_admin' && (p.stations || {})[msg.req.params.id] !== 'admin') return deny(403, 'Anda bukan admin stasiun ini.');
