let daftarPompa = [
    { nama: "laut", alamatCoil: 0x0000 },
    { nama: "tawar", alamatCoil: 0x0001 }
];

// ===== "Sekarang", dalam DETIK (bukan menit lagi) =====
let nowEpochSeconds = Math.floor(Date.now() / 1000);

daftarPompa.forEach(function (p) {
    let jamMulaiSet = flow.get('jam_mulai_' + p.nama) || "00:00";
    let durasiDetik = flow.get('durasi_detik_' + p.nama) || 60;
    let intervalDetik = flow.get('interval_detik_' + p.nama) || 3600;

    let parts = jamMulaiSet.split(":");
    let jamWIB = parseInt(parts[0]);
    let menitWIB = parseInt(parts[1]);
    let jamUTC = jamWIB - 7; // WIB = UTC+7

    let anchorDate = new Date(Date.UTC(2020, 0, 1, jamUTC, menitWIB, 0));
    let anchorEpochSeconds = Math.floor(anchorDate.getTime() / 1000);

    let diff = nowEpochSeconds - anchorEpochSeconds;
    let diffPositif = ((diff % intervalDetik) + intervalDetik) % intervalDetik;
    let isScheduleMatch = (diffPositif === 0);

    node.warn(`🔍 [${p.nama.toUpperCase()}] jam_mulai=${jamMulaiSet} | durasi=${durasiDetik}dtk | interval=${intervalDetik}dtk | now=${nowEpochSeconds} | sisa=${diffPositif} | match=${isScheduleMatch}`);

    if (isScheduleMatch) {
        let lastKey = 'last_triggered_epoch_second_' + p.nama;
        let lastTriggered = flow.get(lastKey) || -1;
        if (lastTriggered !== nowEpochSeconds) {
            flow.set(lastKey, nowEpochSeconds);
            node.warn(`🔥 JADWAL ${p.nama.toUpperCase()} COCOK! Pompa ON selama ${durasiDetik} detik.`);
            jalankanPompa(p.nama, p.alamatCoil, durasiDetik);
        }
    }
});

return null;

function jalankanPompa(nama, alamatCoil, detik) {
    let msgOn = { payload: buatPerintahCoil(0x64, alamatCoil, true) };
    node.send(msgOn);

    let durasiMilidetik = parseInt(detik) * 1000;
    setTimeout(function () {
        let msgOff = { payload: buatPerintahCoil(0x64, alamatCoil, false) };
        node.send(msgOff);
        node.warn(`🛑 Waktu habis, OFF dikirim ke Pompa ${nama.toUpperCase()}.`);
    }, durasiMilidetik);
}

