function crc16Modbus(buffer) {
    let crc = 0xFFFF;
    for (let pos = 0; pos < buffer.length; pos++) {
        crc ^= buffer[pos];
        for (let i = 0; i < 8; i++) {
            if ((crc & 0x0001) !== 0) {
                crc >>= 1;
                crc ^= 0xA001;
            } else {
                crc >>= 1;
            }
        }
    }
    let low = crc & 0xFF;
    let high = (crc >> 8) & 0xFF;
    return Buffer.from([low, high]);
}

function buatPerintahCoil(slaveId, alamatCoil, statusOn) {
    let addrHi = (alamatCoil >> 8) & 0xFF;
    let addrLo = alamatCoil & 0xFF;
    let nilaiHi = statusOn ? 0xFF : 0x00;
    let nilaiLo = 0x00;
    let dataFrame = Buffer.from([slaveId, 0x05, addrHi, addrLo, nilaiHi, nilaiLo]);
    let crc = crc16Modbus(dataFrame);
    return Buffer.concat([dataFrame, crc]);
}

