function crc16Modbus(buffer) {
    let crc = 0xFFFF;
    for (let pos = 0; pos < buffer.length; pos++) {
        crc ^= buffer[pos];
        for (let i = 0; i < 8; i++) {
            if ((crc & 0x0001) !== 0) { crc >>= 1; crc ^= 0xA001; }
            else { crc >>= 1; }
        }
    }
    return Buffer.from([crc & 0xFF, (crc >> 8) & 0xFF]);
}

function buatPerintahCoil(slaveId, alamatCoil, statusOn) {
    let addrHi = (alamatCoil >> 8) & 0xFF;
    let addrLo = alamatCoil & 0xFF;
    let nilaiHi = statusOn ? 0xFF : 0x00;
    let dataFrame = Buffer.from([slaveId, 0x05, addrHi, addrLo, nilaiHi, 0x00]);
    return Buffer.concat([dataFrame, crc16Modbus(dataFrame)]);
}

