function cekDanJalankanPompa(nama) {
    let jamMulai = flow.get('s3_jam_mulai_' + nama) || '00:00';
    let durasiDetik = flow.get('s3_durasi_detik_' + nama) || 60;
    let intervalDetik = flow.get('s3_interval_detik_' + nama) || 3600;

    // Jika jadwal belum pernah disimpan, jangan jalankan pompa
    if (!flow.get('s3_jam_mulai_' + nama)) return null;

    let now = new Date();
    let [jamSet, menitSet] = jamMulai.split(':').map(Number);
    let mulai = new Date();
    mulai.setHours(jamSet, menitSet, 0, 0);

    let detikSejakMulai = (now - mulai) / 1000;
    if (detikSejakMulai < 0) detikSejakMulai += 86400;

    let posisiDalamSiklus = detikSejakMulai % intervalDetik;
    let statusSeharusnya = posisiDalamSiklus < durasiDetik;
    let statusSebelumnya = flow.get('s3_status_pompa_' + nama);

    // Pertama kali jalan: simpan status tanpa kirim perintah
    if (statusSebelumnya === undefined) {
        flow.set('s3_status_pompa_' + nama, statusSeharusnya);
        return null;
    }

    if (statusSeharusnya !== statusSebelumnya) {
        flow.set('s3_status_pompa_' + nama, statusSeharusnya);
        return { pompa: nama, command: statusSeharusnya ? 'ON' : 'OFF' };
    }
    return null;
}

