function crc16(b){let c=0xFFFF;for(const x of b){c^=x;for(let i=0;i<8;i++)c=(c&1)?((c>>1)^0xA001):(c>>1);}return Buffer.from([c&0xFF,(c>>8)&0xFF]);}
function coil(sl,ad,on){const f=Buffer.from([sl,0x05,(ad>>8)&0xFF,ad&0xFF,on?0xFF:0x00,0x00]);return Buffer.concat([f,crc16(f)]);}
const AUDIT='INSERT INTO audit_log (user_id,username,aksi,detail,stasiun_id) VALUES (?,?,?,?,?)';
const aud=(u,a,d,s)=>({topic:AUDIT,payload:[u?u.id:null,u?u.username:'scheduler',a,String(d).slice(0,200),s]});
const st=(flow.get('st_id')||{})[msg.req.params.id];
const b = msg.payload || {};
const SLAVE = { DO: 1, pH: 1, EC: 1 };   // alamat Modbus tiap sensor - SESUAIKAN jika alamat sensor diubah
const titik = parseFloat(b.titik); let reg = null, val = null;
if (b.sensor === 'DO') { reg = 0x1010; if (titik === 100) val = 0x0002; else if (titik === 0) val = 0x0001; }   // SEN0681: 0x0002 = jenuh 100%, 0x0001 = nol
else if (b.sensor === 'EC') { if (titik === 1413) { reg = 0x30; val = 0xFFFF; } else if (titik === 12880) { reg = 0x31; val = 0xFFFF; } }
else if (b.sensor === 'pH') { if (titik === 4.01) { reg = 0x30; val = 0x7FFF; } else if (titik === 7) { reg = 0x31; val = 0x7FFF; } else if (titik === 10.01) { reg = 0x32; val = 0x7FFF; } }
if (!st || reg === null || val === null) { msg.statusCode=400;msg.payload={ok:false,pesan:'Permintaan tidak valid.'}; return [null, null, msg]; }
const f = Buffer.from([SLAVE[b.sensor] || 1, 0x06, (reg >> 8) & 0xFF, reg & 0xFF, (val >> 8) & 0xFF, val & 0xFF]);   // slave sensor = 0x01
msg.statusCode = 200; msg.payload = {ok:true, pesan:'Perintah kalibrasi ' + b.sensor + ' ' + titik + ' dikirim.'};
return [{ topic: st.topic_cmd, payload: Buffer.concat([f, crc16(f)]) }, aud(msg.user, 'kalibrasi', b.sensor + ' ' + titik, st.nama), msg];

msg.topic="SELECT r.* FROM readings r JOIN stations s ON s.nama=r.stasiun_id WHERE s.id=? AND r.timestamp >= NOW() - INTERVAL 30 MINUTE ORDER BY r.timestamp ASC";
msg.payload=[parseInt(msg.req.params.id)||0];
return msg;

const rows = msg.payload || [];
const f = r => new Date(r.timestamp).toLocaleTimeString('id-ID', {hour:'2-digit', minute:'2-digit', timeZone:'Asia/Jakarta'});
const g = rows.filter(r => r.latitude).pop() || {};
msg.statusCode = 200;
msg.payload = { labels: rows.map(f), tds: rows.map(r=>r.tds), ph: rows.map(r=>r.ph), do: rows.map(r=>r.do_mgl), suhu: rows.map(r=>r.do_temperature), salinitas: rows.map(r=>r.salinity), orp: rows.map(r=>r.orp), lat: g.latitude, lng: g.longitude };
return msg;

const ls = (flow.get('lastseen') || {})[msg.req.params.id] || null;
const AMBANG = 20;   // detik tanpa data baru = OFFLINE
const age = ls ? Math.round((Date.now() - ls.t) / 1000) : null;
msg.statusCode = 200;
msg.payload = { online: age !== null && age <= AMBANG, last_seen: ls ? new Date(ls.t).toISOString() : null, age: age, lat: ls ? ls.lat : null, lng: ls ? ls.lng : null };
return msg;

const q = msg.req.query || {};
const ok = s => /^\d{4}-\d{2}-\d{2}$/.test(s || '');
const end = ok(q.end) ? q.end : new Date().toISOString().slice(0, 10);
const start = ok(q.start) ? q.start : new Date(Date.now() - 7 * 864e5).toISOString().slice(0, 10);
msg.topic = 'SELECT r.* FROM readings r JOIN stations s ON s.nama=r.stasiun_id WHERE s.id=? AND r.timestamp BETWEEN ? AND ? ORDER BY r.timestamp ASC';
msg.payload = [parseInt(msg.req.params.id) || 0, start + ' 00:00:00', end + ' 23:59:59'];
msg._label = 'stasiun' + msg.req.params.id + '_' + start + '_sd_' + end;
return msg;

const rows = msg.payload || [];
let csv = 'Tidak ada data pada rentang tanggal yang dipilih.\r\n';
if (rows.length) {
  const cols = Object.keys(rows[0]);
  csv = cols.join(',') + '\r\n' + rows.map(r => cols.map(k => { let v = r[k]; if (v === null || v === undefined) return ''; v = String(v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }).join(',')).join('\r\n') + '\r\n';
}
msg.payload = csv; msg.statusCode = 200;
msg.headers = { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': 'attachment; filename="data_' + msg._label + '.csv"' };
return msg;

msg.topic='SELECT j.pompa,j.jam_mulai,j.durasi_detik,j.interval_detik FROM jadwal_pompa j JOIN stations s ON s.nama=j.stasiun_id WHERE s.id=?';
msg.payload=[parseInt(msg.req.params.id)||0];
