const o = {};
(msg.payload || []).forEach(r => o[r.pompa] = { jam_mulai: String(r.jam_mulai).slice(0, 5), durasi_detik: parseInt(r.durasi_detik), interval_detik: parseInt(r.interval_detik) });
o.laut = o.laut || { jam_mulai: '08:00', durasi_detik: 120, interval_detik: 3600 };
o.tawar = o.tawar || { jam_mulai: '06:00', durasi_detik: 60, interval_detik: 7200 };
msg.statusCode = 200; msg.payload = o; return msg;

const b = msg.payload || {};
msg.pw = String(b.password || '');
msg.topic = 'SELECT u.id,u.username,u.role,u.password_hash,u.is_active,m.station_id,m.role AS srole FROM users u LEFT JOIN station_members m ON m.user_id=u.id WHERE u.username=?';
msg.payload = [String(b.username || '')];
return msg;

const bcrypt = global.get('bcrypt'), jwt = global.get('jwt');
const rows = msg.payload || [], u = rows[0];
if (u && u.is_active && bcrypt.compareSync(msg.pw, u.password_hash)) {
  const stations = {};
  rows.forEach(r => { if (r.station_id) stations[r.station_id] = r.srole; });
  const token = jwt.sign({id:u.id, username:u.username, role:u.role, stations}, env.get('JWT_SECRET'), {expiresIn:'2h'});
  msg.statusCode = 200; msg.payload = {ok:true, token, username:u.username, role:u.role, stations};
} else { msg.statusCode = 401; msg.payload = {ok:false, pesan:'Username/password salah atau akun nonaktif.'}; }
delete msg.pw; return msg;

const bcrypt = global.get('bcrypt');
const {username, email, password} = msg.payload || {};
if (!username || !email || !password || String(password).length < 8 || !/^[A-Za-z0-9_.-]{3,30}$/.test(username)) {
  msg.statusCode = 400; msg.payload = {ok:false, pesan:'Username 3-30 karakter (huruf/angka), email, dan password minimal 8 karakter wajib diisi.'}; return [null, msg];
}
msg.topic = 'INSERT INTO users (username,email,password_hash) VALUES (?,?,?)';
msg.payload = [username, String(email).slice(0,100), bcrypt.hashSync(String(password), 10)];
return [msg, null];

const jwt = global.get('jwt');
const h = msg.req.headers.authorization || '';
msg.me = null;
try { if (h.startsWith('Bearer ')) msg.me = jwt.verify(h.slice(7), env.get('JWT_SECRET')); } catch (e) {}
msg.topic = 'SELECT id,nama,device,lat,lng FROM stations ORDER BY id'; msg.payload = []; return msg;

